import React from 'react';

export type ButtonVariant = 'quiet' | 'expressive' | 'nocturne';
export type ButtonIntent = 'primary' | 'secondary' | 'ghost' | 'danger';
export type ButtonSize = 'sm' | 'md' | 'lg';

export interface ButtonProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  'formAction'
> {
  variant?: ButtonVariant;
  intent?: ButtonIntent;
  size?: ButtonSize;
  icon?: React.ReactNode;
  iconPosition?: 'left' | 'right';
  children?: React.ReactNode;
  label?: string;
  helperText?: string;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      variant = 'quiet',
      intent = 'primary',
      size = 'md',
      icon,
      iconPosition = 'left',
      children,
      label,
      helperText,
      className = '',
      disabled,
      type = 'button',
      ...rest
    },
    ref
  ) => {
    // This primitive does not forward caller-supplied submit destinations.
    const { formAction: ignoredFormAction, ...safeRest } = rest as typeof rest & {
      formAction?: string;
    };
    void ignoredFormAction;
    const helperId = React.useId();
    // Base interactive styles
    const baseClasses =
      'inline-flex items-center justify-center font-medium select-none transition-all duration-150 ease-out focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-40 cursor-pointer active:scale-[0.98] motion-reduce:transition-none motion-reduce:active:scale-100';

    // Size mappings
    const sizeClasses = {
      sm: 'h-8 px-3 text-xs gap-1.5 rounded-[var(--tess-radius-md,8px)]',
      md: 'h-9 px-4 text-sm gap-2 rounded-[var(--tess-radius-lg,8px)]',
      lg: 'h-11 px-5 text-base gap-2.5 rounded-[var(--tess-radius-xl,8px)]',
    }[size];

    // Variant & Intent styling matrix
    let colorClasses = '';

    if (variant === 'quiet') {
      // Quiet: Restrained, subtle, monochrome, minimal contrast for high data density shells
      switch (intent) {
        case 'primary':
          colorClasses =
            'bg-neutral-900 text-white hover:bg-neutral-800 border border-neutral-900 shadow-sm focus-visible:ring-neutral-900 focus-visible:ring-offset-white';
          break;
        case 'secondary':
          colorClasses =
            'bg-white text-neutral-800 hover:bg-neutral-50 hover:text-neutral-900 border border-neutral-300 shadow-xs focus-visible:ring-neutral-400 focus-visible:ring-offset-white';
          break;
        case 'ghost':
          colorClasses =
            'bg-transparent text-[var(--tess-ink-secondary,#62666F)] hover:bg-neutral-100 hover:text-neutral-900 border border-transparent focus-visible:ring-neutral-400';
          break;
        case 'danger':
          colorClasses =
            'bg-rose-50 text-rose-700 hover:bg-rose-100 border border-rose-200 focus-visible:ring-rose-500';
          break;
      }
    } else if (variant === 'expressive') {
      // Expressive: Cobalt interactive system emphasis, tactile elevation, spring-like feel
      switch (intent) {
        case 'primary':
          colorClasses =
            'bg-[var(--tess-accent-primary,#2547E8)] text-[var(--tess-accent-ink,#FFFFFF)] hover:bg-[#1E3CCD] border border-[#2547E8] shadow-sm hover:shadow-md focus-visible:ring-[#2547E8] focus-visible:ring-offset-white';
          break;
        case 'secondary':
          colorClasses =
            'bg-white text-[#2547E8] hover:bg-[#E7EBFF] border border-[#D9D6CF] shadow-xs focus-visible:ring-[#2547E8] focus-visible:ring-offset-white';
          break;
        case 'ghost':
          colorClasses =
            'bg-transparent text-[#2547E8] hover:bg-[#E7EBFF] border border-transparent focus-visible:ring-[#2547E8]';
          break;
        case 'danger':
          colorClasses =
            'bg-[#C83D48] text-white hover:bg-[#A92A34] border border-[#C83D48] shadow-sm focus-visible:ring-[#C83D48] focus-visible:ring-offset-white';
          break;
      }
    } else {
      // Nocturne: Deep obsidian canvas, razor-sharp hairline borders, luminescence
      switch (intent) {
        case 'primary':
          colorClasses =
            'bg-white text-neutral-950 hover:bg-neutral-200 border border-white shadow-sm focus-visible:ring-white focus-visible:ring-offset-neutral-950';
          break;
        case 'secondary':
          colorClasses =
            'bg-[#171A21] text-neutral-100 hover:bg-[#20242D] border border-[#2E3440] shadow-xs focus-visible:ring-[#2547E8] focus-visible:ring-offset-neutral-950';
          break;
        case 'ghost':
          colorClasses =
            'bg-transparent text-neutral-400 hover:bg-[#171A21] hover:text-neutral-100 border border-transparent focus-visible:ring-[#2547E8]';
          break;
        case 'danger':
          colorClasses =
            'bg-[#2A1518] text-[#FF6B7A] hover:bg-[#3D1D22] border border-[#522329] focus-visible:ring-[#FF6B7A] focus-visible:ring-offset-neutral-950';
          break;
      }
    }

    const button = (
      <button
        ref={ref}
        type={type}
        disabled={disabled}
        aria-describedby={disabled && helperText ? helperId : undefined}
        className={`${baseClasses} ${sizeClasses} ${colorClasses} ${className}`}
        {...safeRest}
      >
        {icon && iconPosition === 'left' && <span className="inline-flex shrink-0">{icon}</span>}
        {children ?? label ?? 'Example action'}
        {icon && iconPosition === 'right' && <span className="inline-flex shrink-0">{icon}</span>}
      </button>
    );

    if (!disabled || !helperText) return button;

    return (
      <span className="inline-flex flex-col items-start gap-1">
        {button}
        <span id={helperId} className="text-xs text-[var(--tess-ink-muted,#62666F)]">
          {helperText}
        </span>
      </span>
    );
  }
);

Button.displayName = 'Button';

import React, { useState } from 'react';
import { Button, type ButtonVariant, type ButtonIntent, type ButtonSize } from './index.js';

export interface ButtonPreviewProps {
  initialVariant?: ButtonVariant;
  initialIntent?: ButtonIntent;
  initialSize?: ButtonSize;
  label?: string;
}

export function ButtonPreview({
  initialVariant = 'expressive',
  initialIntent = 'primary',
  initialSize = 'md',
  label = 'Interactive Button',
}: ButtonPreviewProps) {
  const [variant, setVariant] = useState<ButtonVariant>(initialVariant);
  const [intent, setIntent] = useState<ButtonIntent>(initialIntent);
  const [size, setSize] = useState<ButtonSize>(initialSize);
  const [clickCount, setClickCount] = useState(0);

  const isDark = variant === 'nocturne';

  return (
    <div
      className={`min-h-full w-full p-8 transition-colors duration-200 ${
        isDark ? 'bg-[#0B0D10] text-neutral-100' : 'bg-[#FAF9F6] text-neutral-900'
      }`}
    >
      <div className="mx-auto max-w-2xl space-y-8">
        {/* Live Interactive Stage */}
        <div
          className={`rounded-2xl border p-8 flex flex-col items-center justify-center gap-6 shadow-sm ${
            isDark ? 'border-[#1E232E] bg-[#11141B]' : 'border-[#E5E2DA] bg-white'
          }`}
        >
          <div className="flex flex-wrap items-center justify-center gap-4 py-6">
            <Button
              variant={variant}
              intent={intent}
              size={size}
              onClick={() => setClickCount((c) => c + 1)}
            >
              {label} {clickCount > 0 && `(${clickCount})`}
            </Button>
            <Button variant={variant} intent="secondary" size={size}>
              Secondary
            </Button>
            <Button variant={variant} intent="ghost" size={size}>
              Ghost
            </Button>
            <Button variant={variant} intent="danger" size={size}>
              Danger
            </Button>
          </div>

          <div className="flex items-center gap-2 text-xs opacity-60">
            <span>Click count: {clickCount}</span>
            <span>•</span>
            <span>Focusable via Tab</span>
            <span>•</span>
            <span>Enter / Space trigger</span>
          </div>
        </div>

        {/* Curated Configurations Comparison */}
        <div className="space-y-4">
          <h3 className="text-xs font-semibold uppercase tracking-wider opacity-60">
            Curated Launch Configurations
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* Quiet */}
            <div
              onClick={() => setVariant('quiet')}
              className={`cursor-pointer rounded-xl border p-4 transition-all ${
                variant === 'quiet'
                  ? 'border-[#2547E8] ring-2 ring-[#2547E8]/20 bg-white'
                  : 'border-[#E5E2DA] bg-white hover:border-neutral-400'
              } text-neutral-900`}
            >
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-semibold">Quiet</span>
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-neutral-100 text-neutral-600 uppercase font-mono">
                  Default
                </span>
              </div>
              <p className="text-xs text-neutral-500 mb-4 line-clamp-2">
                Monochrome, minimal contrast for high data density shells.
              </p>
              <div className="flex gap-2">
                <Button variant="quiet" intent="primary" size="sm">
                  Primary
                </Button>
                <Button variant="quiet" intent="secondary" size="sm">
                  Cancel
                </Button>
              </div>
            </div>

            {/* Expressive */}
            <div
              onClick={() => setVariant('expressive')}
              className={`cursor-pointer rounded-xl border p-4 transition-all ${
                variant === 'expressive'
                  ? 'border-[#2547E8] ring-2 ring-[#2547E8]/20 bg-white'
                  : 'border-[#E5E2DA] bg-white hover:border-neutral-400'
              } text-neutral-900`}
            >
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-semibold">Expressive</span>
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-[#E7EBFF] text-[#2547E8] uppercase font-mono">
                  Accent
                </span>
              </div>
              <p className="text-xs text-neutral-500 mb-4 line-clamp-2">
                Cobalt primary, tactile elevation and hover lift.
              </p>
              <div className="flex gap-2">
                <Button variant="expressive" intent="primary" size="sm">
                  Deploy
                </Button>
                <Button variant="expressive" intent="secondary" size="sm">
                  Draft
                </Button>
              </div>
            </div>

            {/* Nocturne */}
            <div
              onClick={() => setVariant('nocturne')}
              className={`cursor-pointer rounded-xl border p-4 transition-all ${
                variant === 'nocturne'
                  ? 'border-[#2547E8] ring-2 ring-[#2547E8]/40 bg-[#11141B]'
                  : 'border-[#222733] bg-[#11141B] hover:border-neutral-600'
              } text-neutral-100`}
            >
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-semibold">Nocturne</span>
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-[#1C202C] text-neutral-300 uppercase font-mono">
                  Dark
                </span>
              </div>
              <p className="text-xs text-neutral-400 mb-4 line-clamp-2">
                Obsidian dark canvas with crisp luminescence.
              </p>
              <div className="flex gap-2">
                <Button variant="nocturne" intent="primary" size="sm">
                  Execute
                </Button>
                <Button variant="nocturne" intent="secondary" size="sm">
                  Inspect
                </Button>
              </div>
            </div>
          </div>
        </div>

        {/* Live Controls */}
        <div
          className={`rounded-xl border p-4 flex flex-wrap items-center justify-between gap-4 text-xs ${
            isDark ? 'border-[#1E232E] bg-[#11141B]' : 'border-[#E5E2DA] bg-white'
          }`}
        >
          <div className="flex items-center gap-2">
            <span className="font-semibold opacity-70">Intent:</span>
            {(['primary', 'secondary', 'ghost', 'danger'] as ButtonIntent[]).map((i) => (
              <button
                key={i}
                type="button"
                onClick={() => setIntent(i)}
                className={`px-2 py-1 rounded capitalize font-medium transition-colors ${
                  intent === i
                    ? 'bg-[#2547E8] text-white'
                    : isDark
                      ? 'bg-neutral-800 text-neutral-300 hover:bg-neutral-700'
                      : 'bg-neutral-100 text-neutral-700 hover:bg-neutral-200'
                }`}
              >
                {i}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-2">
            <span className="font-semibold opacity-70">Size:</span>
            {(['sm', 'md', 'lg'] as ButtonSize[]).map((s) => (
              <button
                key={s}
                type="button"
                onClick={() => setSize(s)}
                className={`px-2 py-1 rounded uppercase font-medium transition-colors ${
                  size === s
                    ? 'bg-[#2547E8] text-white'
                    : isDark
                      ? 'bg-neutral-800 text-neutral-300 hover:bg-neutral-700'
                      : 'bg-neutral-100 text-neutral-700 hover:bg-neutral-200'
                }`}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default ButtonPreview;
